function boardDateSummary(list){
  const iso=v=>{const s=String(v||'').slice(0,10),y=String(TODAY_ISO||'').slice(0,4)||String(new Date().getFullYear());return /^\d{4}-\d{2}-\d{2}$/.test(s)?s:/^\d{2}-\d{2}$/.test(s)?`${y}-${s}`:'';};
  const dates=list.flatMap(t=>[iso(t.start),iso(t.due)]).filter(Boolean).sort();
  const from=F.dateFrom||dates[0]||'',to=F.dateTo||dates[dates.length-1]||'';
  const text=from||to?`${from?fmtDate(from,true):'‡∏ß‡∏±‡∏ô‡πÅ‡∏£‡∏Å'} ‚Äì ${to?fmtDate(to,true):'‡∏ß‡∏±‡∏ô‡∏•‡πà‡∏≤‡∏™‡∏∏‡∏î'}`:'‡∏¢‡∏±‡∏á‡πÑ‡∏°‡πà‡∏°‡∏µ‡∏ß‡∏±‡∏ô‡∏ó‡∏µ‡πà‡πÉ‡∏ô‡∏£‡∏≤‡∏¢‡∏Å‡∏≤‡∏£';
  const mode=F.dateFrom||F.dateTo?'‡∏ä‡πà‡∏ß‡∏á‡∏ß‡∏±‡∏ô‡∏ó‡∏µ‡πà‡∏ó‡∏µ‡πà‡πÄ‡∏•‡∏∑‡∏≠‡∏Å':'‡∏ä‡πà‡∏ß‡∏á‡∏ß‡∏±‡∏ô‡∏ó‡∏µ‡πà‡∏Ç‡∏≠‡∏á‡∏£‡∏≤‡∏¢‡∏Å‡∏≤‡∏£‡∏ó‡∏µ‡πà‡πÅ‡∏™‡∏î‡∏á';
  return `<div class="board-date-summary" role="status"><span>${sic('i-calendar')} ${mode}</span><strong>${esc(text)}</strong><small>‡∏ß‡∏±‡∏ô‡πÄ‡∏£‡∏¥‡πà‡∏°‡πÅ‡∏•‡∏∞‡∏ß‡∏±‡∏ô‡∏™‡πà‡∏á‡πÅ‡∏™‡∏î‡∏á‡πÅ‡∏¢‡∏Å‡πÉ‡∏ô‡∏ï‡∏≤‡∏£‡∏≤‡∏á‡∏î‡πâ‡∏≤‡∏ô‡∏•‡πà‡∏≤‡∏á</small></div>`;
}

